import React, { useState, useEffect, useRef } from "react";

const KaraokePlaceholder = ({ text, audioSrc, readingMode }) => {
  const [highlightIndex, setHighlightIndex] = useState(-1);
  const audioRef = useRef(null);
  const rafRef = useRef(null);

  const startKaraoke = () => {
    if (!readingMode || !audioRef.current) return;

    const audio = audioRef.current;
    setHighlightIndex(-1);

    audio.currentTime = 0;
    audio.play().catch(err => {
      console.error("Audio play failed:", err);
    });

    const animate = () => {
      if (!text || text.length === 0) return;
      const duration = audio.duration;
      if (!duration || isNaN(duration)) return;

      const progress = audio.currentTime / duration;
      const index = Math.floor(progress * text.length);

      if (index < text.length) {
        setHighlightIndex(index);
      }

      if (!audio.paused && !audio.ended) {
        rafRef.current = requestAnimationFrame(animate);
      }
    };

    rafRef.current = requestAnimationFrame(animate);

    audio.onended = () => {
      cancelAnimationFrame(rafRef.current);
      setHighlightIndex(-1); // reset
    };
  };

  useEffect(() => {
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  return (
    <span
      onMouseEnter={startKaraoke}
      style={{
        display: "inline-block",
        writingMode: "vertical-rl",
        textOrientation: "mixed",
        whiteSpace: "normal",
        wordBreak: "break-word",
        lineHeight: "1.8em",
        fontFamily: '"Mongolian Baiti", "Noto Sans Mongolian", sans-serif',
        fontSize: "14px",
        cursor: readingMode ? "pointer" : "default"
      }}
    >
      {text.split("").map((ch, i) => (
        <span
          key={i}
          style={{
            color: i <= highlightIndex && highlightIndex !== -1 ? "red" : "inherit",
            transition: "color 0.1s linear"
          }}
        >
          {ch}
        </span>
      ))}
      <audio ref={audioRef} src={audioSrc} preload="metadata" />
    </span>
  );
};

export default KaraokePlaceholder;
