import React, { useState, useEffect, useRef } from "react";
import { Typography, Tooltip, Box } from "@mui/material";

const HoverTranslationWithKaraoke = ({
  traditionalText,
  cyrillicText,
  language,
  variant,
  lang,
  audioSrc,
  readingMode,
  sx,
}) => {
  const [hovered, setHovered] = useState(false);
  const [highlightIndex, setHighlightIndex] = useState(-1);
  const audioRef = useRef(null);
  const rafRef = useRef(null);

  const handleMouseEnter = () => {
    setHovered(true);

    if (!readingMode || !audioSrc) return;

    const audio = new Audio(audioSrc);
    audioRef.current = audio;
    setHighlightIndex(-1);

    audio.currentTime = 0;
    audio.play().catch((err) => console.error("Audio play failed:", err));

    const text = language === "traditional" ? traditionalText : cyrillicText;

    const animate = () => {
      if (!text || text.length === 0) return;
      const duration = audio.duration;
      if (!duration || isNaN(duration)) {
        rafRef.current = requestAnimationFrame(animate);
        return;
      }

      const progress = audio.currentTime / duration;
      const index = Math.floor(progress * text.length);
      setHighlightIndex(index);

      if (!audio.paused && !audio.ended) {
        rafRef.current = requestAnimationFrame(animate);
      }
    };

    rafRef.current = requestAnimationFrame(animate);

    audio.onended = () => {
      cancelAnimationFrame(rafRef.current);
      setHighlightIndex(-1);
    };
  };

  const handleMouseLeave = () => {
    setHovered(false);
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    cancelAnimationFrame(rafRef.current);
    setHighlightIndex(-1);
  };

  useEffect(() => {
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  const displayText = language === "traditional" ? traditionalText : cyrillicText;
  const tooltipText = language === "traditional" ? cyrillicText : traditionalText;

  return (
    <Tooltip title={tooltipText} placement="top" arrow>
      <Box
        sx={{
          position: "relative",
          display: "inline-block",
          cursor: 'help',
        }}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        {/* Base text (gray or default) */}
        <Typography
          variant={variant}
          lang={lang}
          sx={{
            writingMode: language === "traditional" ? "vertical-rl" : "horizontal-tb",
            textOrientation: language === "traditional" ? "mixed" : "upright",
            color: "inherit",
            ...sx,
          }}
        >
          {displayText}
        </Typography>

        {/* Highlighted overlay (red up to highlightIndex) */}
        {highlightIndex >= 0 && (
          <Typography
            variant={variant}
            lang={lang}
            sx={{
              writingMode: language === "traditional" ? "vertical-rl" : "horizontal-tb",
              textOrientation: language === "traditional" ? "mixed" : "upright",
              position: "absolute",
              top: 0,
              left: 0,
              color: "red",
              pointerEvents: "none",
              clipPath: language === "traditional"
                ? `inset(0 0 ${100 - (highlightIndex / displayText.length) * 100}% 0)`
                : `inset(0 ${100 - (highlightIndex / displayText.length) * 100}% 0 0)`,
              ...sx,
            }}
          >
            {displayText}
          </Typography>
        )}
      </Box>
    </Tooltip>
  );
};

export default HoverTranslationWithKaraoke;
